mod common;
use common::run_php;

#[test]
fn amd64_integer_literal_boundaries_match_php_85() {
    assert_eq!(
        run_php(
            r#"<?php
var_dump(9223372036854775807);
var_dump(9223372036854775808);
var_dump(-9223372036854775808);
var_dump(0x7fffffffffffffff);
var_dump(0x8000000000000000);
var_dump(0b111111111111111111111111111111111111111111111111111111111111111);
var_dump(0b1111111111111111111111111111111111111111111111111111111111111111);
var_dump(0o777777777777777777777);
var_dump(0o1000000000000000000000);
var_dump(0777777777777777777777);
var_dump(01000000000000000000000);
var_dump(01_6, 0b1_010110, 0x8_000000000000000);
var_dump();
"#,
        ),
        "int(9223372036854775807)\nfloat(9.223372036854776E+18)\nfloat(-9.223372036854776E+18)\nint(9223372036854775807)\nfloat(9.223372036854776E+18)\nint(9223372036854775807)\nfloat(1.844674407370955E+19)\nint(9223372036854775807)\nfloat(9.223372036854776E+18)\nint(9223372036854775807)\nfloat(9.223372036854776E+18)\nint(14)\nint(86)\nfloat(9.223372036854776E+18)\nfloat(INF)\n"
    );
}
